import java.io.*;
import java.util.*;

class Catatan {
    static void simpan(String nama, List<String> baris) throws IOException {
        try (PrintWriter w = new PrintWriter(new FileWriter(nama))) {
            for (String b : baris) {
                w.println(b);
            }
        }
    }

    static List<String> baca(String nama) throws IOException {
        List<String> hasil = new ArrayList<>();
        try (BufferedReader r = new BufferedReader(new FileReader(nama))) {
            String b;
            while ((b = r.readLine()) != null) {
                hasil.add(b);
            }
        }
        return hasil;
    }
}

public class MainB {
    public static void main(String[] args) throws IOException {
        Catatan.simpan("harian.txt", Arrays.asList("beli keripik", "telepon Bu Ida", "beli petis"));
